var r=`0115-rosolje`;var n=`world-0115`;var i=`EE`;var o=`northern-europe`;var s=4;var a=46;var l={en:`Rosolje`,ua:`Розольє`};var g={en:`A classic dish from Estonia, featuring beetroot, potato, carrot, salted herring. A practical home-kitchen version with measured step ingredients and clear cooking methods.`,ua:`Класична страва з Естонія. Основні складники: буряк, картопля, морква, солоний оселедець. Домашній варіант із поетапними діями та точними кількостями продуктів.`};var d=[{en:`Cook the listed ingredients in simmering water for about 30 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 30 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:30,i:[[`beetroot`,380,`g`],[`potato`,280,`g`],[`carrot`,150,`g`],[`water`,900,`ml`]]},{en:`Wash and prepare the listed produce; dice or chop evenly for a consistent texture.`,ua:`Вимийте й підготуйте зазначені продукти; наріжте рівномірними кубиками або дрібними шматочками.`,t:[`chopping`,`dicing`],m:10,i:[[`salted-herring`,260,`g`],[`fermented-cucumber`,180,`g`],[`yellow-onion`,110,`g`]]},{en:`Fold in the dressing ingredients, season to taste and serve, or chill briefly as appropriate.`,ua:`Обережно змішайте із заправкою, приправте до смаку й подавайте або трохи охолодіть за потреби.`,t:[`tossing`,`seasoning`],m:6,i:[[`sour-cream`,160,`g`],[`apple-cider-vinegar`,15,`ml`],[`table-salt`,null,`to_taste`],[`ground-black-pepper`,null,`to_taste`]]}];var c={slug:r,id:n,country:`EE`,region:o,servings:4,minutes:46,title:l,text:g,steps:d};export{i as country,c as default,n as id,a as minutes,o as region,s as servings,r as slug,d as steps,g as text,l as title};